extern "C" { extern const char page_html[] = R"PAGE(<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Disco</title>
<meta name="theme-color" content="#182538"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Disco"><meta name="apple-mobile-web-app-status-bar-style" content="default">
<link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" sizes="180x180" href="/apple-touch-icon.png"><link rel="icon" type="image/png" sizes="192x192" href="/icon-192.png">
<style>
:root{font:15px system-ui,sans-serif;color:#182538;background:#eef2f6;accent-color:#245ce5}*{box-sizing:border-box}body{margin:0}main{max-width:900px;margin:32px auto;padding:0 20px 40px}header{display:flex;align-items:baseline;gap:16px;margin-bottom:24px}h1{font-size:38px;letter-spacing:-2px;margin:0}header span,.hint,.size{color:#637286}section{background:#fff;border:1px solid #dde4ed;border-radius:16px;padding:24px;margin:16px 0}h2{font-size:21px;margin:0 0 20px}label{display:block;font-weight:600;margin-bottom:8px}select,button,input{font:inherit}select{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:inherit}button{padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;background:white;color:inherit;cursor:pointer}button:hover{background:#edf2ff}button:disabled,select:disabled{opacity:.45;cursor:default}.primary{background:#245ce5;color:white;border-color:#245ce5}.danger{color:#b3263d}#stop{background:#182538;color:#fff;min-width:85px}.row{display:flex;align-items:center;justify-content:space-between;gap:12px}.hint{font-size:13px;line-height:1.5}.transport{margin:18px 0}.timeline{flex:1}progress{width:100%;height:8px;display:block;border:0;border-radius:9px;overflow:hidden}progress::-webkit-progress-bar{background:#e6ebf2}progress::-webkit-progress-value{background:#245ce5}.times{margin-top:8px;font-variant-numeric:tabular-nums;font-size:13px}input[type=range]{width:100%;margin:8px 0}.volume{margin-top:24px}.compact{padding:0;margin:12px 0 0;list-style:none}.compact li{display:flex;gap:10px;align-items:center;padding:9px 0;border-top:1px solid #edf0f4}.filename{flex:1;min-width:0;overflow-wrap:anywhere}.size{font-size:12px;white-space:nowrap}.compact button{font-size:12px;padding:6px 9px}#queue{max-height:250px;overflow:auto;counter-reset:tracks}#queue li{counter-increment:tracks;font-size:13px}#queue li:before{content:counter(tracks,decimal-leading-zero);color:#8290a3;min-width:23px}#drop{border:2px dashed #bac9dd;border-radius:12px;padding:24px;text-align:center;background:#f8faff;margin:12px 0}#drop.over{background:#e4edff;border-color:#245ce5}#files{max-width:100%;margin-top:12px}#status{white-space:pre-line;font-size:14px;padding:12px 16px;background:#e3eaf5;border-radius:10px}#status.error{background:#ffeded;color:#9a2331}[hidden]{display:none!important}@media(max-width:560px){main{padding:0 12px;margin:20px auto}section{padding:18px}header span{font-size:12px}.compact li{flex-wrap:wrap}.filename{flex-basis:60%}}
#connection{margin-left:auto;display:inline-flex;gap:8px;align-items:center;font-size:13px;white-space:nowrap}#connectionDot{width:11px;height:11px;border-radius:50%;background:#c43b45;box-shadow:0 0 0 4px #c43b4512}#connection.online #connectionDot{background:#23925b;box-shadow:0 0 0 4px #23925b12}details{margin-top:24px;border-top:1px solid #dde4ed;padding-top:18px}summary{cursor:pointer;font-weight:600}#htmlFile{max-width:100%;margin:10px 0}details .row{justify-content:flex-start;flex-wrap:wrap}header{flex-wrap:wrap}

/* Touch controls, safe areas and narrow screens; browser zoom stays available. */
body{min-height:100vh;min-height:100dvh}main{padding-left:max(20px,env(safe-area-inset-left));padding-right:max(20px,env(safe-area-inset-right));padding-top:env(safe-area-inset-top);padding-bottom:max(40px,env(safe-area-inset-bottom))}
button,select,input,summary{font-size:16px}button,select,summary{min-height:44px}button,summary{touch-action:manipulation}summary{padding:10px 0}input[type=range]{min-height:44px;touch-action:pan-y}input[type=file]{width:100%;min-width:0}input[type=file]::file-selector-button{font:inherit;min-height:44px;border:1px solid #cbd5e1;border-radius:8px;background:white;margin-right:8px;padding:8px}
:focus-visible{outline:3px solid #245ce5;outline-offset:3px}.row>*{min-width:0}.timeline{min-width:0}#picked,#status,#playerState,#queue li{overflow-wrap:anywhere}#queue{overscroll-behavior:contain}.app-icon{width:48px;height:48px;border-radius:12px;flex:none}header{align-items:center}header .subtitle{flex:1;min-width:120px}
@media(max-width:560px){main{margin:16px auto;padding-left:max(12px,env(safe-area-inset-left));padding-right:max(12px,env(safe-area-inset-right))}section{padding:16px}h1{font-size:32px}h2{font-size:20px}header{gap:12px}header .subtitle{flex-basis:calc(100% - 72px);order:3}#connection{margin-left:auto}.compact button{font-size:14px;min-height:44px}.compact li{gap:8px}#list li{display:grid;grid-template-columns:1fr auto}#list .filename{grid-column:1 / -1}#list .size{grid-column:1 / -1}#list button{width:100%}#urnPanel>.row{flex-wrap:wrap}#drop{padding:16px 10px}details .row button{width:100%}#fileTitle{margin-bottom:0}.transport{gap:16px}}
</style></head><body>
<main><header><img class="app-icon" src="/icon-192.png" alt="" width="48" height="48"><h1>Disco</h1><span id="connection" role="status" aria-live="polite"><i id="connectionDot" aria-hidden="true"></i><span id="connectionText">Vérification…</span></span></header>
<section aria-labelledby="lecture"><h2 id="lecture">Lecture</h2><label for="track">Morceau</label><select id="track"><option value="">Choisir un morceau…</option></select><p id="playerState" class="hint">Connexion au lecteur…</p><div class="row transport"><div class="timeline"><progress id="playProgress" max="1" value="0" aria-label="Progression de lecture"></progress><div class="row times"><span id="elapsed">0:00</span><span id="duration">0:00</span></div></div><button id="stop">STOP</button></div><div class="volume"><div class="row"><label for="volume">Volume</label><output id="volumeValue">55 %</output></div><input id="volume" type="range" min="0" max="100" value="55"><div class="hint">Appliqué et mémorisé au relâchement du curseur.</div></div></section>
<section aria-labelledby="modeTitle"><h2 id="modeTitle">Mode de fonctionnement</h2><label for="mode">Sélection au démarrage</label><select id="mode"><option value="random">Random</option><option value="urn">Urne</option></select><p class="hint">Le mode est mémorisé pour les prochains allumages. Les écoutes manuelles ne consomment pas l’urne.</p><div id="urnPanel"><div class="row"><span id="urnInfo" class="hint"></span><button id="resetUrn" data-idle>Régénérer la liste</button></div><ol id="queue" class="compact"></ol></div></section>
<section aria-labelledby="fileTitle"><div class="row"><h2 id="fileTitle">Fichiers</h2><button id="refresh">Actualiser</button></div><div id="drop"><strong>Déposer des fichiers WAV ici</strong><div class="hint">ou sélectionner des fichiers sur cet appareil</div><input id="files" data-idle type="file" accept=".wav" multiple><p id="picked" class="hint">Aucun fichier sélectionné</p><button id="send" data-idle class="primary">Téléverser</button></div><p class="hint">PCM 16 bits · mono ou stéréo · 44,1 ou 48 kHz · <span id="limit">128 Mio maximum par fichier</span></p><progress id="uploadProgress" max="100" value="0" hidden aria-label="Progression du téléversement"></progress><p id="fileLock" class="hint" hidden>Appuyer sur STOP pour téléverser, renommer, supprimer ou régénérer l’urne.</p><ul id="list" class="compact"></ul><details><summary>Mettre à jour l’interface Web</summary><p class="hint">Dossier <code>/www</code> sur la SD : index.html, CSS, JavaScript et images. Liens relatifs autorisés, sans sous-dossiers. Les fichiers du même nom sont remplacés. <span id="htmlLimit">1 Mio maximum par fichier.</span> Appuyer sur STOP avant modification.</p><label for="htmlFile">Fichiers Web</label><input id="htmlFile" data-idle type="file" accept=".html,.css,.js,.png,.jpg,.jpeg,.gif,.webp,.svg,.ico,.json,.woff2" multiple><div class="row"><button id="uploadHtml" data-idle class="primary">Téléverser les fichiers Web</button><button id="refreshWeb">Actualiser la liste</button><button id="resetHtml" data-idle>Restaurer la page embarquée</button><a href="/">Ouvrir l’interface</a></div><ul id="webFiles" class="compact"></ul><progress id="htmlProgress" max="100" value="0" hidden aria-label="Téléversement HTML"></progress><p class="hint">En cas de problème, ouvrir la <a href="/recovery">page de secours embarquée</a>.</p></details></section><div id="status" role="status" aria-live="polite">Connexion…</div></main>
<script>
'use strict';
const $=id=>document.getElementById(id);let busy=false,playing=false,dirty=false,polling=false,picked=[],maxBytes=128*1024*1024,connected=null,reloading=false,maxHtmlBytes=1024*1024;
function message(t,error=false){$('status').textContent=t;$('status').classList.toggle('error',error);}
function controls(){document.querySelectorAll('button,input,select').forEach(e=>e.disabled=busy||connected!==true);document.querySelectorAll('[data-idle]').forEach(e=>e.disabled=busy||playing||connected!==true);$('stop').disabled=busy||!playing||connected!==true;$('fileLock').hidden=!playing;}
function lock(v){busy=v;controls();}
async function json(url){const c=new AbortController(),t=setTimeout(()=>c.abort(),4000);try{const r=await fetch(url,{cache:'no-store',signal:c.signal});if(!r.ok)throw Error(await r.text());return await r.json();}finally{clearTimeout(t);}}
async function api(url,headers={}){const c=new AbortController(),timer=setTimeout(()=>c.abort(),10000);try{const r=await fetch(url,{method:'POST',signal:c.signal,headers:{'X-Manage':'1',...headers}});const t=await r.text();if(!r.ok)throw Error(t);return t;}finally{clearTimeout(timer);}}
function clock(ms){const s=Math.floor(Math.max(0,ms||0)/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');}
async function refreshPlayer(updateTrack=true){const d=await json('/api/player');playing=d.playing;$('playerState').textContent=(playing?'En lecture : '+d.name:'À l’arrêt')+(d.error?' — '+d.error:'');if(updateTrack)$('track').value=playing?d.name:'';$('elapsed').textContent=clock(d.elapsedMs);$('duration').textContent=clock(d.durationMs);$('playProgress').max=d.durationMs||1;$('playProgress').value=Math.min(d.elapsedMs||0,d.durationMs||0);if(!dirty){$('volume').value=d.volume;$('volumeValue').textContent=d.volume+' %';}controls();}
async function refreshUrn(){const d=await json('/api/urn');$('mode').value=d.mode;$('urnPanel').hidden=d.mode!=='urn';$('queue').replaceChildren();if(d.mode!=='urn')return;const q=d.queue||[];$('urnInfo').textContent=!d.ready?'Urne indisponible':q.length?q.length+' à venir / '+d.total:d.total?'Urne vide · mélange au prochain allumage':'Aucun WAV compatible';q.forEach(name=>{const li=document.createElement('li');li.textContent=name;$('queue').append(li);});}
async function refreshFiles(){const d=await json('/api/files');maxBytes=d.maxBytes;$('limit').textContent=Math.round(maxBytes/1024/1024)+' Mio maximum par fichier';$('list').replaceChildren();$('track').replaceChildren(new Option('Choisir un morceau…',''));d.files.sort((a,b)=>a.name.localeCompare(b.name,'fr')).forEach(f=>{const li=document.createElement('li'),name=document.createElement('span'),size=document.createElement('span');name.className='filename';name.textContent=f.name;size.className='size';size.textContent=(f.size/1024/1024).toFixed(2)+' Mio';li.append(name,size);for(const [label,fn]of [['Renommer',()=>renameFile(f.name)],['Supprimer',()=>deleteFile(f.name)]]){const b=document.createElement('button');b.textContent=label;b.dataset.idle='';b.onclick=fn;if(label==='Supprimer')b.className='danger';li.append(b);}$('list').append(li);$('track').add(new Option(f.name,f.name));});if(!d.files.length)$('list').textContent='Aucun fichier WAV.';if(d.truncated)message('Liste limitée aux 1024 premiers fichiers.');controls();}
async function refresh(){await refreshFiles();await refreshUrn();await refreshPlayer();await refreshWebFiles();}
async function action(fn){if(busy||connected!==true)return;lock(true);try{await fn();}catch(e){message(e.message,true);}finally{lock(false);}}
$('track').onchange=()=>{const name=$('track').value;if(name)action(async()=>{try{message(await api('/api/play',{'X-File-Name':encodeURIComponent(name)}));}finally{await refreshPlayer();}});};
$('stop').onclick=()=>action(async()=>{message(await api('/api/stop'));await refreshPlayer();});
$('volume').oninput=()=>{dirty=true;$('volumeValue').textContent=$('volume').value+' %';};
$('volume').onchange=()=>action(async()=>{try{message(await api('/api/volume',{'X-Volume':$('volume').value}));}finally{dirty=false;await refreshPlayer();}});
$('mode').onchange=()=>action(async()=>{try{message(await api('/api/mode',{'X-Mode':$('mode').value}));}finally{await refreshUrn();}});
$('resetUrn').onclick=()=>action(async()=>{message(await api('/api/urn/reset'));await refreshUrn();});
async function renameFile(name){if(busy||playing)return;const next=prompt('Nouveau nom (avec .wav)',name);if(next===null||next===name)return;await action(async()=>{message(await api('/api/rename',{'X-File-Name':encodeURIComponent(name),'X-New-Name':encodeURIComponent(next.trim())}));await refresh();});}
async function deleteFile(name){if(busy||playing||!confirm('Supprimer « '+name+' » ?'))return;await action(async()=>{message(await api('/api/delete',{'X-File-Name':encodeURIComponent(name)}));await refresh();});}
function choose(files){picked=Array.from(files);$('picked').textContent=picked.length?picked.length+' fichier(s) : '+picked.map(f=>f.name).join(', '):'Aucun fichier sélectionné';}
$('files').onchange=()=>choose($('files').files);
for(const type of ['dragenter','dragover'])$('drop').addEventListener(type,e=>{e.preventDefault();if(!busy&&!playing)$('drop').classList.add('over');});
for(const type of ['dragleave','drop'])$('drop').addEventListener(type,e=>{e.preventDefault();$('drop').classList.remove('over');});
$('drop').addEventListener('drop',e=>{if(busy||playing){message('Appuyer sur STOP avant de téléverser.',true);return;}choose(e.dataTransfer.files);});
window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
function upload(file,route='/api/upload',progress='uploadProgress'){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST',route);x.timeout=15*60*1000;x.setRequestHeader('Content-Type','application/octet-stream');x.setRequestHeader('X-Manage','1');x.setRequestHeader('X-File-Name',encodeURIComponent(file.name));x.upload.onprogress=e=>{if(e.lengthComputable)$(progress).value=e.loaded/e.total*100;};x.onload=()=>x.status>=200&&x.status<300?resolve():reject(Error(x.responseText||'Échec du transfert'));x.onerror=()=>reject(Error('Connexion interrompue'));x.ontimeout=()=>reject(Error('Délai de transfert dépassé'));x.send(file);});}
$('send').onclick=()=>{if(playing)return;if(!picked.length){message('Choisir au moins un WAV.');return;}action(async()=>{$('uploadProgress').hidden=false;const results=[];try{for(const f of picked){message('Téléversement : '+f.name);$('uploadProgress').value=0;try{if(!/\.wav$/i.test(f.name)||f.size===0)throw Error('Fichier WAV requis');if(f.size>maxBytes)throw Error('Limite dépassée');await upload(f);results.push('✓ '+f.name);}catch(e){results.push('✗ '+f.name+' : '+e.message);}}await refresh();message(results.join('\n'),results.some(x=>x.startsWith('✗')));}finally{$('uploadProgress').hidden=true;$('files').value='';choose([]);}});};
$('refresh').onclick=()=>action(async()=>{await refresh();message('Actualisé.');});
function setConnection(ok){
 const previous=connected;connected=ok;
 $('connection').classList.toggle('online',ok);$('connectionText').textContent=ok?'Connecté':'Déconnecté';
 if(previous!==ok){
  controls();
  if(!ok){playing=false;dirty=false;$('playerState').textContent='Lecteur déconnecté — attente de reconnexion…';$('track').value='';$('elapsed').textContent='—';$('duration').textContent='—';$('playProgress').value=0;message('Connexion perdue. La page sera rechargée au retour du lecteur.',true);controls();}
  else if(previous===false&&!reloading){reloading=true;message('Connexion rétablie. Rechargement…');location.reload();}
 }
}
async function checkConnection(){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),3000);
 try{const r=await fetch('/api/ping',{cache:'no-store',signal:controller.signal});if(!r.ok)throw Error('ping');const d=await r.json();if(d.disco!==true)throw Error('Réponse inattendue');maxHtmlBytes=d.maxHtmlBytes||1024*1024;$('htmlLimit').textContent=Math.round(maxHtmlBytes/1024)+' Kio maximum par fichier.';setConnection(true);return true;}
 catch(e){setConnection(false);return false;}finally{clearTimeout(timer);}
}
async function refreshWebFiles(){const d=await json('/api/ui/files');$('webFiles').replaceChildren();for(const f of d.files){const li=document.createElement('li'),name=document.createElement('span'),size=document.createElement('span'),del=document.createElement('button');name.className='filename';name.textContent=f.name;size.className='size';size.textContent=(f.size/1024).toFixed(1)+' Kio';del.textContent='Supprimer';del.className='danger';del.dataset.idle='';del.onclick=()=>{if(confirm('Supprimer '+f.name+' du dossier /www ?'))action(async()=>{message(await api('/api/ui/delete',{'X-File-Name':encodeURIComponent(f.name)}));await refreshWebFiles();});};li.append(name,size,del);$('webFiles').append(li);}if(!d.files.length)$('webFiles').textContent='Dossier /www vide.';if(d.truncated)message('Liste limitée à 256 fichiers Web.');controls();}
$('refreshWeb').onclick=()=>action(refreshWebFiles);
$('uploadHtml').onclick=()=>{const files=Array.from($('htmlFile').files);if(!files.length){message('Choisir des fichiers Web.',true);return;}action(async()=>{$('htmlProgress').hidden=false;const results=[];try{files.sort((a,b)=>(a.name.toLowerCase()==='index.html')-(b.name.toLowerCase()==='index.html'));for(const f of files){try{if(!/\.(html|css|js|png|jpe?g|gif|webp|svg|ico|json|woff2)$/i.test(f.name)||!f.size||f.size>maxHtmlBytes)throw Error('Format, taille ou fichier vide invalide');message('Téléversement : '+f.name);$('htmlProgress').value=0;await upload(f,'/api/ui/upload','htmlProgress');results.push('✓ '+f.name);}catch(e){results.push('✗ '+f.name+' : '+e.message);break;}}await refreshWebFiles();message(results.join('\n')+'\nOuvrir l’interface pour voir les changements.',results.some(x=>x.startsWith('✗')));}finally{$('htmlProgress').hidden=true;$('htmlFile').value='';}});};
$('resetHtml').onclick=()=>{if(!confirm('Supprimer /www/index.html et revenir à la page embarquée ? Les autres fichiers sont conservés.'))return;action(async()=>{message(await api('/api/ui/reset'));location.assign('/');});};
window.addEventListener('offline',()=>setConnection(false));
async function monitor(){if(busy||polling||reloading)return;polling=true;try{if(await checkConnection()&&!reloading)await refreshPlayer(document.activeElement!==$('track'));}catch(e){message('Lecteur joignable, mais actualisation impossible : '+e.message,true);}finally{polling=false;}}
// The single-threaded ESP HTTP server receives uploads synchronously: do not
// interpret its occupied connection as an outage. Resume monitoring afterwards.
setInterval(monitor,1500);
(async()=>{polling=true;try{if(await checkConnection())await action(async()=>{await refresh();message('Prêt. Écoute sur la sortie jack.');});}finally{polling=false;}})();
document.addEventListener('visibilitychange',()=>{if(!document.hidden)monitor();});
window.addEventListener('pageshow',()=>monitor());
</script></body></html>
)PAGE"; }
